// Recorre cada ejecución y saca los tokens de CADA llamada al modelo (sub-nodo)
const filas = [];
for (const item of $input.all()) {
  const ex = item.json;
  const runData = ex.data?.resultData?.runData || {};
  for (const [nodo, runs] of Object.entries(runData)) {
    runs.forEach((run, i) => {
      const salida = run.data?.ai_languageModel?.[0]?.[0]?.json;
      if (!salida) return; // no es un nodo de modelo
      const real = salida.tokenUsage;
      const estimado = salida.tokenUsageEstimate;
      const u = real || estimado || {};
      filas.push({ json: {
        ejecucion_id: ex.id,
        fecha: ex.startedAt,
        workflow_id: ex.workflowId,
        nodo_modelo: nodo,
        llamada_n: i + 1,
        promptTokens: u.promptTokens ?? null,
        completionTokens: u.completionTokens ?? null,
        totalTokens: u.totalTokens ?? null,
        fuente: real ? 'real (API del proveedor)' : (estimado ? 'estimado por n8n' : 'sin dato')
      }});
    });
  }
}
return filas.length ? filas : [{ json: { aviso: 'No encontré llamadas a modelos en estas ejecuciones' } }];

// Un renglón por ejecución: total de llamadas y tokens
const por = {};
for (const { json: f } of $input.all()) {
  if (!f.ejecucion_id) continue;
  const r = por[f.ejecucion_id] ??= { ejecucion_id: f.ejecucion_id, fecha: f.fecha, llamadas_al_modelo: 0, promptTokens: 0, completionTokens: 0, totalTokens: 0, fuente: f.fuente };
  r.llamadas_al_modelo++;
  r.promptTokens += f.promptTokens || 0;
  r.completionTokens += f.completionTokens || 0;
  r.totalTokens += f.totalTokens || 0;
}
return Object.values(por).map(json => ({ json }));
